#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORDS 65536
#define MAX_LEN 64

typedef struct {
    char word[MAX_LEN];
    int count;
} Entry;

static Entry table[MAX_WORDS];
static int n_entries = 0;

static void add_word(const char *w) {
    for (int i = 0; i < n_entries; i++) {
        if (strcmp(table[i].word, w) == 0) {
            table[i].count++;
            return;
        }
    }
    if (n_entries < MAX_WORDS) {
        strncpy(table[n_entries].word, w, MAX_LEN - 1);
        table[n_entries].count = 1;
        n_entries++;
    }
}

static int by_count(const void *a, const void *b) {
    const Entry *x = a, *y = b;
    if (y->count != x->count) return y->count - x->count;
    return strcmp(x->word, y->word);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 2;
    }
    FILE *fp = fopen(argv[1], "r");
    if (!fp) { perror(argv[1]); return 1; }
    char buf[MAX_LEN]; int len = 0; int c;
    while ((c = fgetc(fp)) != EOF) {
        if (isalpha(c)) {
            if (len < MAX_LEN - 1) buf[len++] = tolower(c);
        } else if (len > 0) {
            buf[len] = '\0'; add_word(buf); len = 0;
        }
    }
    if (len > 0) { buf[len] = '\0'; add_word(buf); }
    fclose(fp);
    qsort(table, n_entries, sizeof(Entry), by_count);
    for (int i = 0; i < n_entries && i < 10; i++)
        printf("%d %s\n", table[i].count, table[i].word);
    return 0;
}
